def read_csv(line, fields):
    """
    Given a CSV line and a list of field names, parse the line into a dictionary
    mapping the field names to the corresponding values.
    """
    lines = fields
    data = {}
    count = 0
    while count < len(line):
        # Check for the end of the line
        if line[count] == "" and count + 1 < len(line):
            lines = lines[:count]
            data = {lines[i]: data.get(lines[i], "") for i in range(len(lines))}
            count += 2
        elif line[count] == "," and count + 1 < len(line):
            lines = lines[:count] + [""] + lines[count + 1:]
            data.update({lines[i]: data.get(lines[i], "") for i in range(len(lines))})
            count += 2
        elif line[count] == "," and count + 1 == len(line):
            count += 2
    return data


