    if node:
        visit(node)
        preorder(node.left, visit)
        preorder(node.right, visit)


def buildTree(nums):
    if not nums:
        return None
    root = TreeNode(nums[0])
    queue = deque([root])
    idx = 0
    while queue:
        node = queue.popleft()
        if node:
            mid = (idx + 1) // 2
            node.left = TreeNode(nums[mid])
            queue.append(node.left)
            if node.left:
                queue.append(node.left)
            mid = (idx + 1) // 2
            node.right = TreeNode(nums[idx])
            queue.append(node.right)
            if node.right:
                queue.append(node.right)
            idx += 1
    return root


